import { $ } from '@tooooools/ui/state'

const Pointer = {
  $pageX: $(-1),
  $pageY: $(-1),
  $clientX: $(-1),
  $clientY: $(-1),
  $pressed: $(false),
  $lastPressed: $(undefined),
  $target: $(undefined)
}

export default Pointer

document.documentElement.addEventListener('pointermove', e => {
  const touch = window.TouchEvent && (e instanceof TouchEvent)
    ? e.targetTouches[0]
    : null

  Pointer.$pageX.value = touch?.pageX ?? e.pageX
  Pointer.$pageY.value = touch?.pageY ?? e.pageY
  Pointer.$clientX.value = touch?.clientX ?? e.clientX
  Pointer.$clientY.value = touch?.clientY ?? e.clientY
  Pointer.$target.value = touch?.target ?? e.target
})

document.documentElement.addEventListener('pointerdown', e => {
  Pointer.$pressed.value = true
  Pointer.$lastPressed.value = Date.now()
})

document.documentElement.addEventListener('pointerup', e => {
  window.setTimeout(() => {
    Pointer.$pressed.value = false
  })
})
